package io.fireflysoftware.domain.accounting.core.posting.impl;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import io.fireflysoftware.domain.accounting.core.posting.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.fireflyframework.cqrs.command.CommandBus;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
class ManagedPostingServiceTest {
    static final String TENANT=new UUID(0,1).toString(),BOOK=new UUID(0,2).toString(),ACTION=new UUID(0,3).toString(),DIGEST="a".repeat(64);
    byte[] body(String currency){return ("{\"expectedIntentDigest\":\""+DIGEST+"\",\"posting\":{\"actionId\":\""+ACTION+"\",\"source\":{\"owner\":\"LEDGER\",\"eventKind\":\"COMMIT\",\"revision\":1,\"effectOrdinal\":0},\"entries\":[{\"lines\":[{\"currency\":{\"isoCode\":\""+currency+"\"},\"postedScale\":2},{\"currency\":{\"isoCode\":\""+currency+"\"},\"postedScale\":2}]}]}}").getBytes(StandardCharsets.UTF_8);}
    @Test void cqrsUsesTheCallerActionAndCapturedBodyWithoutGeneratingNewIdentity(){var bus=mock(CommandBus.class);var seen=new AtomicReference<ManagedPostingCommand>();when(bus.send(any(ManagedPostingCommand.class))).thenAnswer(call->{var command=call.getArgument(0,ManagedPostingCommand.class);seen.set(command);return Mono.just(new ManagedPostingResponse(command.actionId(),command.expectedIntentDigest(),ManagedPostingResponse.Status.OUTCOME_UNKNOWN,null,null));});var bytes=body("USD");var operation=new ManagedPostingServiceImpl(bus).submit(TENANT,BOOK,bytes,false);Arrays.fill(bytes,(byte)'x');assertEquals(UUID.fromString(ACTION),operation.block().actionId());assertEquals(ACTION,readAction(seen.get()));assertFalse(seen.get().recovery());verify(bus,times(1)).send(any(ManagedPostingCommand.class));}
    String readAction(ManagedPostingCommand command){try{return new com.fasterxml.jackson.databind.ObjectMapper().readTree(command.originalPostingJson()).path("actionId").textValue();}catch(Exception invalid){throw new AssertionError(invalid);}}
    @Test void recoveryRetainsTheSameCompleteCapturedIntent(){var bus=mock(CommandBus.class);var seen=new ArrayList<ManagedPostingCommand>();when(bus.send(any(ManagedPostingCommand.class))).thenAnswer(call->{var command=call.getArgument(0,ManagedPostingCommand.class);seen.add(command);return Mono.just(new ManagedPostingResponse(command.actionId(),command.expectedIntentDigest(),ManagedPostingResponse.Status.OUTCOME_UNKNOWN,null,null));});var service=new ManagedPostingServiceImpl(bus);service.submit(TENANT,BOOK,body("USD"),false).block();service.submit(TENANT,BOOK,body("USD"),true).block();assertEquals(seen.get(0).actionId(),seen.get(1).actionId());assertEquals(seen.get(0).originalPostingJson(),seen.get(1).originalPostingJson());assertEquals(seen.get(0).expectedIntentDigest(),seen.get(1).expectedIntentDigest());assertTrue(seen.get(1).recovery());}
    @Test void unsupportedCurrencyCannotReachCommandBus(){var bus=mock(CommandBus.class);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->new ManagedPostingServiceImpl(bus).submit(TENANT,BOOK,body("EUR"),false).block());verifyNoInteractions(bus);}
    @Test void duplicateAndUnknownOriginalFieldsCannotDisappearBeforeOwner(){for(String variant:List.of("duplicate","unknown","floating","null")){var raw=new String(body("USD"),StandardCharsets.UTF_8);raw=switch(variant){case"duplicate"->raw.replace("\"revision\":1","\"revision\":1,\"revision\":1");case"unknown"->raw.replace("\"actionId\":","\"unexpectedAuthority\":true,\"actionId\":");case"floating"->raw.replace("\"revision\":1","\"revision\":1.0");default->raw.replace("\"effectOrdinal\":0","\"effectOrdinal\":null");};var bytes=raw.getBytes(StandardCharsets.UTF_8);var bus=mock(CommandBus.class);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->new ManagedPostingServiceImpl(bus).submit(TENANT,BOOK,bytes,false).block(),variant);verifyNoInteractions(bus);}}
    @Test void absentResultDoesNotBecomeSuccessfulPosting(){var bus=mock(CommandBus.class);when(bus.send(any(ManagedPostingCommand.class))).thenReturn(Mono.empty());assertEquals(ManagedPostingResponse.Status.OUTCOME_UNKNOWN,new ManagedPostingServiceImpl(bus).submit(TENANT,BOOK,body("USD"),false).block().status());verify(bus,times(1)).send(any(ManagedPostingCommand.class));}
    @Test void commandAndTokenDiagnosticsNeverRenderPayloadOrBearer(){var token=new ManagedPostingCallerToken("aaa.bbb.ccc");assertFalse(token.toString().contains("aaa"));var command=new ManagedPostingCommand(TENANT,BOOK,UUID.fromString(ACTION),DIGEST,"sensitive-original-body",false);assertFalse(command.toString().contains("sensitive-original-body"));}
    @Test void unexpectedCqrsFailureCannotLoseOriginalActionCorrelation(){var bus=mock(CommandBus.class);when(bus.send(any(ManagedPostingCommand.class))).thenReturn(Mono.error(new IllegalStateException("ambiguous dispatch")));var response=new ManagedPostingServiceImpl(bus).submit(TENANT,BOOK,body("USD"),false).block();assertEquals(UUID.fromString(ACTION),response.actionId());assertEquals(DIGEST,response.intentDigest());assertEquals(ManagedPostingResponse.Status.OUTCOME_UNKNOWN,response.status());verify(bus,times(1)).send(any(ManagedPostingCommand.class));}
    @Test void cqrsWrappedExplicitPreDispatchRefusalPreservesItsPhase(){var bus=mock(CommandBus.class);when(bus.send(any(ManagedPostingCommand.class))).thenReturn(Mono.error(new IllegalStateException("handler refused",new ManagedPostingPreDispatchException(org.springframework.http.HttpStatus.FORBIDDEN))));var error=assertThrows(ManagedPostingPreDispatchException.class,()->new ManagedPostingServiceImpl(bus).submit(TENANT,BOOK,body("USD"),false).block());assertEquals(403,error.getStatusCode().value());verify(bus,times(1)).send(any(ManagedPostingCommand.class));}

}
